const html = `<!doctype html><html><head><meta name="viewport" content="width=device-width,initial-scale=1"><title>INK / Manga Studio</title><style>
*{box-sizing:border-box}body{margin:0;background:#191b20;color:#ecece9;font:16px system-ui}button,input,select{font:inherit}button{cursor:pointer;border:1px solid #41434b;background:#282b32;color:inherit;border-radius:6px;padding:10px 14px}button:hover,button.active{background:#d9ff63;color:#151713;border-color:#d9ff63}header{height:76px;border-bottom:1px solid #393b42;display:flex;align-items:center;padding:0 28px;gap:28px}.logo{font-weight:950;font-size:32px;letter-spacing:-3px}.logo span{color:#d9ff63}small{color:#a7a9b2}nav{display:flex;gap:8px;margin-left:auto}.app{display:grid;grid-template-columns:220px 1fr 250px;min-height:calc(100vh - 76px)}aside{padding:22px 18px;border-right:1px solid #393b42}aside.right{border-left:1px solid #393b42;border-right:0}h3{font-size:12px;letter-spacing:2px;color:#b7bac3;margin:24px 0 12px}h2{font-size:20px}.tools{display:grid;grid-template-columns:1fr 1fr;gap:8px}.tools button{padding:14px 5px;font-size:14px}.workspace{padding:22px 30px;overflow:auto;background:radial-gradient(#34373d 1px,transparent 1px) 0 0/16px 16px}.bar{display:flex;align-items:center;gap:8px;margin-bottom:20px}.bar input{background:transparent;color:white;border:0;font-weight:700;width:100%;min-width:70px}#paper{display:block;background:white;width: min(100%,600px);height:auto;margin:0 auto;box-shadow:0 12px 40px #0008;touch-action:none}select,input[type=text],textarea{width:100%;padding:9px;border:1px solid #4c4e57;border-radius:5px;background:#23262d;color:white}label{display:block;color:#bdc0c9;font-size:14px;margin:18px 0 8px}input[type=range]{width:100%;accent-color:#d9ff63}.presets{display:flex;gap:6px;flex-wrap:wrap}.presets button{font-size:13px}.primary{background:#d9ff63;color:#171a13;font-weight:700}.pages{display:flex;gap:8px;justify-content:center;margin:20px}.muted{font-size:13px;color:#aaaeb8;line-height:1.6}#library{padding:35px;max-width:1100px;margin:auto}#shelf{display:grid;grid-template-columns:repeat(auto-fill,minmax(200px,1fr));gap:25px}.card{background:#262930;padding:16px;border:1px solid #42454e;border-radius:8px}.card img{width:100%;aspect-ratio:2/3;object-fit:cover}.badge{color:#d9ff63;font-size:12px;letter-spacing:2px}.hidden{display:none!important}dialog{max-width:900px;width:95%;background:#22252b;color:white;border:1px solid #555;border-radius:12px}dialog img{width:100%;display:block;margin:15px auto}#notice{position:fixed;bottom:22px;left:50%;transform:translateX(-50%);background:#d9ff63;color:#151713;padding:12px 22px;border-radius:6px;z-index:9;display:none}@media(max-width:1000px){.app{grid-template-columns:150px 1fr}.right{grid-column:1/-1;display:flex;gap:20px;flex-wrap:wrap}.right>*{max-width:180px}.workspace{padding:16px}header{gap:12px;padding:12px}header small{display:none}}@media(max-width:600px){.app{grid-template-columns:1fr}aside{border-bottom:1px solid #444}.tools{grid-template-columns:repeat(4,1fr)}header{height:auto;flex-wrap:wrap}nav{margin:0}nav button{padding:8px}.workspace{padding:10px}}
</style></head><body><header><div class="logo">INK<span>/</span></div><small>YOUR NEXT CHAPTER STARTS HERE</small><nav><button id="studioNav" class="active">Studio</button><button id="coverNav">Cover designer</button><button id="libraryNav">Library</button></nav><button id="publish" class="primary">Publish manga</button></header><main id="editor" class="app"><aside><div class="badge">MANGA WORKSPACE</div><h2>Make your mark.</h2><h3>DRAWING TOOLS</h3><div class="tools" id="tools"><button data-tool="pen" class="active">✒ G-pen</button><button data-tool="pencil">✎ Pencil</button><button data-tool="eraser">▱ Eraser</button><button data-tool="tone">▦ Tone</button><button data-tool="bubble">◯ Bubble</button><button data-tool="text">T Text</button><button data-tool="move">↔ Move</button><button data-tool="line">╱ Line</button></div><h3>PAGE LAYOUT</h3><div class="presets"><button data-layout="0">Blank</button><button data-layout="1">2 panels</button><button data-layout="2">4 panels</button><button data-layout="3">Hero + 2</button><button data-layout="4">6 panels</button></div><h3>WORKFLOW</h3><p class="muted">Draw on the page. Drag to place bubbles, text and tones. Use Move to reposition lettering and bubbles.</p><button id="importBtn">Import artwork</button><input id="import" type="file" accept="image/*" hidden></aside><section class="workspace"><div class="bar"><input id="title" value="Untitled manga" aria-label="Manga title"><button id="undo">Undo</button><button id="redo">Redo</button><button id="download">PNG</button></div><canvas id="paper" width="800" height="1120"></canvas><div class="pages"><button id="prev">Previous</button><button id="pageLabel">Page 1 / 1</button><button id="next">Next</button><button id="add">+ Page</button></div><p class="muted" style="text-align:center">800 × 1120 px · Autosaved to this browser · Draw your story, one panel at a time</p></section><aside class="right"><div><h3>TOOL PROPERTIES</h3><label>Ink colour</label><input type="color" id="color" value="#151515"><label>Brush size <span id="sizeLabel">5 px</span></label><input type="range" id="size" min="1" max="60" value="5"><label>Screen tone</label><select id="tone"><option value="dots">Classic dots</option><option value="lines">Hatching</option><option value="gray">Soft gray</option></select></div><div><h3>LETTERING</h3><label>Bubble / text content</label><textarea id="words" rows="3">Your story starts here!</textarea><label>Font</label><select id="font"><option value="sans-serif">Manga Sans</option><option value="serif">Classic Serif</option><option value="monospace">Typewriter</option><option value="cursive">Handwritten</option></select><label>Font size</label><input id="fontSize" type="range" min="16" max="64" value="28"><label>Bubble style</label><select id="bubbleStyle"><option>Speech</option><option>Thought</option><option>Caption</option></select><button id="updateText" style="margin-top:12px">Update selected</button></div><div><h3>PROJECT</h3><button id="exportProject">Save project file</button><button id="loadProject" style="margin-top:8px">Open project file</button><input type="file" id="projectFile" accept="application/json" hidden><p class="muted">Keep a project file to continue editing on another device. Published editions are saved in your site library.</p></div></aside></main><section id="library" class="hidden"><div class="badge">THE BOOKSHELF</div><h1>Your stories, in print.</h1><p class="muted">Published editions. Open a book to read every page.</p><div id="shelf"></div></section><dialog id="reader"><button onclick="this.parentElement.close()">Close reader</button><div id="readerPages"></div></dialog><div id="notice"></div><script>
const $=id=>document.getElementById(id),c=$('paper'),g=c.getContext('2d');let tool='pen',page=0,cover=false,selected=-1,start=null,path=null,history=[],future=[],project={title:'Untitled manga',pages:[{layout:3,items:[]}],cover:{layout:0,items:[]}};try{project=JSON.parse(localStorage.getItem('ink-project'))||project}catch{}function sheet(){return cover?project.cover:project.pages[page]}function save(){project.title=$('title').value;localStorage.setItem('ink-project',JSON.stringify(project))}function checkpoint(){history.push(JSON.stringify(project));if(history.length>40)history.shift();future=[]}function notice(s){$('notice').textContent=s;$('notice').style.display='block';setTimeout(()=>$('notice').style.display='none',3200)}function render(){g.fillStyle='white';g.fillRect(0,0,800,1120);g.strokeStyle='#151515';g.lineWidth=4;let l=sheet().layout;const box=(x,y,w,h)=>g.strokeRect(x,y,w,h);if(l===1){box(40,40,720,510);box(40,570,720,510)}if(l===2||l===4){let rows=l===2?2:3;for(let r=0;r<rows;r++)for(let col=0;col<2;col++)box(40+370*col,40+r*(1040/rows+8),350,1040/rows-16)}if(l===3){box(40,40,720,570);box(40,630,350,450);box(410,630,350,450)}sheet().items.forEach((o,i)=>{g.save();g.strokeStyle=o.color||'#151515';g.fillStyle=o.color||'#151515';g.lineWidth=o.size||3;g.lineCap='round';g.lineJoin='round';if(o.type==='stroke'){g.strokeStyle=o.erase?'white':o.color;for(let j=1;j<o.points.length;j++){g.lineWidth=o.size*(o.points[j][2]||1);g.beginPath();g.moveTo(...o.points[j-1]);g.lineTo(...o.points[j]);g.stroke()}}else if(o.type==='line'){g.beginPath();g.moveTo(o.x,o.y);g.lineTo(o.x+o.w,o.y+o.h);g.stroke()}else if(o.type==='image'){let im=new Image();im.src=o.src;if(im.complete)g.drawImage(im,o.x,o.y,o.w,o.h);else im.onload=render}else if(o.type==='tone'){g.save();g.beginPath();g.rect(o.x,o.y,o.w,o.h);g.clip();if(o.pattern==='gray'){g.fillStyle='#bbb';g.fillRect(o.x,o.y,o.w,o.h)}else if(o.pattern==='dots'){for(let x=o.x;x<o.x+o.w;x+=10)for(let y=o.y;y<o.y+o.h;y+=10){g.beginPath();g.arc(x,y,2,0,Math.PI*2);g.fill()}}else{g.lineWidth=1;for(let x=o.x-o.h;x<o.x+o.w;x+=9){g.beginPath();g.moveTo(x,o.y);g.lineTo(x+o.h,o.y+o.h);g.stroke()}}g.restore()}else{if(o.type==='bubble'){g.fillStyle='white';g.lineWidth=3;g.beginPath();if(o.style==='Caption')g.rect(o.x,o.y,o.w,o.h);else g.ellipse(o.x+o.w/2,o.y+o.h/2,o.w/2,o.h/2,0,0,Math.PI*2);g.fill();g.stroke();if(o.style==='Speech'){g.beginPath();g.moveTo(o.x+o.w*.55,o.y+o.h-4);g.lineTo(o.x+o.w*.35,o.y+o.h+30);g.lineTo(o.x+o.w*.4,o.y+o.h-4);g.fill();g.stroke()}if(o.style==='Thought'){[12,7].forEach((r,j)=>{g.beginPath();g.arc(o.x+o.w*.35-j*14,o.y+o.h+15+j*18,r,0,7);g.fill();g.stroke()})}}g.fillStyle=o.color;g.font=o.fontSize+'px '+o.font;g.textAlign='center';let lines=[],s='';o.text.split(/\s+/).forEach(w=>{if(g.measureText(s+w).width>o.w-28&&s){lines.push(s);s=''}s+=w+' '});lines.push(s);lines.forEach((t,j)=>g.fillText(t.trim(),o.x+o.w/2,o.y+o.h/2+(j-(lines.length-1)/2)*o.fontSize*1.2+o.fontSize*.35))}if(i===selected&&tool==='move'&&o.w){g.strokeStyle='#799d15';g.setLineDash([6,4]);g.strokeRect(o.x-4,o.y-4,o.w+8,o.h+8)}g.restore()});$('pageLabel').textContent=cover?'Cover':('Page '+(page+1)+' / '+project.pages.length)}function point(e){let r=c.getBoundingClientRect();return [(e.clientX-r.left)*800/r.width,(e.clientY-r.top)*1120/r.height,e.pressure&&e.pointerType==='pen'?Math.max(.15,e.pressure*2):1]}c.onpointerdown=e=>{e.preventDefault();c.setPointerCapture(e.pointerId);checkpoint();let p=point(e);start=p;if(tool==='move'){selected=sheet().items.findLastIndex(o=>o.w&&p[0]>=o.x&&p[0]<=o.x+o.w&&p[1]>=o.y&&p[1]<=o.y+o.h);render();return}if(['pen','pencil','eraser'].includes(tool)){path={type:'stroke',points:[p,[p[0]+.1,p[1]+.1,p[2]]],size:tool==='pencil'?2:+$('size').value,color:$('color').value,erase:tool==='eraser'};sheet().items.push(path);render()}};c.onpointermove=e=>{if(!start)return;let p=point(e);if(path){path.points.push(p);render()}else if(tool==='move'&&selected>=0){let o=sheet().items[selected];o.x+=p[0]-start[0];o.y+=p[1]-start[1];start=p;render()}};c.onpointerup=e=>{if(!start)return;let p=point(e),x=Math.min(start[0],p[0]),y=Math.min(start[1],p[1]),w=Math.abs(p[0]-start[0]),h=Math.abs(p[1]-start[1]);if(['bubble','text','tone','line'].includes(tool)){if(w<15){w=260;h=tool==='text'?90:150}let o={type:tool,x,y,w,h,color:$('color').value,size:+$('size').value,text:$('words').value,font:$('font').value,fontSize:+$('fontSize').value,style:$('bubbleStyle').value,pattern:$('tone').value};sheet().items.push(o);selected=sheet().items.length-1}start=path=null;render();save()};c.onpointercancel=()=>{start=path=null;save()};document.querySelectorAll('[data-tool]').forEach(b=>b.onclick=()=>{tool=b.dataset.tool;document.querySelectorAll('[data-tool]').forEach(x=>x.classList.toggle('active',x===b));render()});document.querySelectorAll('[data-layout]').forEach(b=>b.onclick=()=>{checkpoint();sheet().layout=+b.dataset.layout;render();save()});$('size').oninput=()=>$('sizeLabel').textContent=$('size').value+' px';$('title').value=project.title;$('title').oninput=save;$('undo').onclick=()=>{if(history.length){future.push(JSON.stringify(project));project=JSON.parse(history.pop());render();save()}};$('redo').onclick=()=>{if(future.length){history.push(JSON.stringify(project));project=JSON.parse(future.pop());render();save()}};$('add').onclick=()=>{checkpoint();project.pages.push({layout:0,items:[]});page=project.pages.length-1;cover=false;render();save()};$('prev').onclick=()=>{page=Math.max(0,page-1);render()};$('next').onclick=()=>{page=Math.min(project.pages.length-1,page+1);render()};function mode(v){cover=v==='cover';$('editor').classList.toggle('hidden',v==='library');$('library').classList.toggle('hidden',v!=='library');['studio','cover','library'].forEach(k=>$(k+'Nav').classList.toggle('active',k===v));selected=-1;render();if(v==='library')library()}$('studioNav').onclick=()=>mode('studio');$('coverNav').onclick=()=>mode('cover');$('libraryNav').onclick=()=>mode('library');function download(data,name){let a=document.createElement('a');a.href=data;a.download=name;a.click()}$('download').onclick=()=>{selected=-1;render();download(c.toDataURL(),'manga-'+(cover?'cover':page+1)+'.png')};$('exportProject').onclick=()=>download('data:application/json;charset=utf-8,'+encodeURIComponent(JSON.stringify(project)),'manga-project.json');$('loadProject').onclick=()=>$('projectFile').click();$('projectFile').onchange=async e=>{try{let p=JSON.parse(await e.target.files[0].text());if(!Array.isArray(p.pages)||!p.pages.length||!p.cover)throw Error();checkpoint();project=p;page=0;$('title').value=p.title;render();save()}catch{notice('Could not open this project file.')}};$('importBtn').onclick=()=>$('import').click();$('import').onchange=e=>{let f=e.target.files[0];if(!f)return;let r=new FileReader();r.onload=()=>{let im=new Image();im.onload=()=>{checkpoint();sheet().items.push({type:'image',src:r.result,x:40,y:40,w:720,h:Math.min(1040,720*im.height/im.width)});render();save()};im.src=r.result};r.readAsDataURL(f)};$('updateText').onclick=()=>{let o=sheet().items[selected];if(!o||!['text','bubble'].includes(o.type))return notice('Select lettering with the Move tool first.');checkpoint();Object.assign(o,{text:$('words').value,font:$('font').value,fontSize:+$('fontSize').value,color:$('color').value,style:$('bubbleStyle').value});render();save()};$('publish').onclick=async()=>{let title=project.title.trim();if(!title)return notice('Give your manga a title first.');$('publish').disabled=true;try{let old=page,wasCover=cover;selected=-1;cover=true;render();let coverImage=c.toDataURL('image/png');let pages=project.pages.map((_,i)=>{cover=false;page=i;render();return c.toDataURL('image/png')});cover=wasCover;page=old;render();let r=await fetch('/api/books',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({title,cover:coverImage,pages})});if(!r.ok)throw Error();notice('Published to your library.');mode('library')}catch{notice('Publishing failed. Please try again.')}finally{$('publish').disabled=false}};async function library(){let shelf=$('shelf');shelf.textContent='Loading editions…';try{let r=await fetch('/api/books');if(!r.ok)throw Error();let books=await r.json();shelf.textContent='';if(!books.length)shelf.textContent='Your bookshelf is ready for its first story.';books.forEach(b=>{let card=document.createElement('div');card.className='card';let im=document.createElement('img');im.src=b.cover;im.alt=b.title;let h=document.createElement('h2');h.textContent=b.title;let p=document.createElement('p');p.className='muted';p.textContent=b.pages.length+' pages · '+new Date(b.date).toLocaleDateString();let btn=document.createElement('button');btn.textContent='Read manga';btn.onclick=()=>{$('readerPages').textContent='';[b.cover,...b.pages].forEach(src=>{let i=new Image();i.src=src;i.alt=b.title+' page';$('readerPages').append(i)});$('reader').showModal()};card.append(im,h,p,btn);shelf.append(card)})}catch{shelf.textContent='Could not load the library. Please try again.'}}render();
</script></body></html>`;
export default {async fetch(request,env){const u=new URL(request.url);if(u.pathname==='/api/books'){if(!env.BUCKET)return new Response('Storage unavailable',{status:503});if(request.method==='POST'){try{const b=await request.json();if(typeof b.title!=='string'||!Array.isArray(b.pages)||b.pages.length>100||JSON.stringify(b).length>24000000)return new Response('Invalid book',{status:400});b.id=crypto.randomUUID();b.date=new Date().toISOString();await env.BUCKET.put('books/'+b.id,JSON.stringify(b));return Response.json({id:b.id})}catch{return new Response('Invalid request',{status:400})}}const list=await env.BUCKET.list({prefix:'books/'});const books=await Promise.all(list.objects.map(async o=>JSON.parse(await (await env.BUCKET.get(o.key)).text())));return Response.json(books.sort((a,b)=>b.date.localeCompare(a.date)))}return new Response(html,{headers:{'content-type':'text/html;charset=utf-8'}})}};
